// Shared UI localization (independent from browser locale) + theme helper.
// Supports "auto" (follow browser language / OS color scheme) plus the full
// SUPPORTED_LANGS list below.

// The full set of 54 supported locale codes, spelled exactly the way this
// file names its region variants below — en_GB/en_US, es_419, pt_BR/pt_PT,
// zh_CN/zh_TW use an underscore, matching chrome.i18n's own locale-folder
// naming convention, while every other code is the plain two/three-letter
// tag.
export type Lang =
  | "ar" | "am" | "bg" | "bn" | "ca" | "cs" | "da" | "de" | "el" | "en"
  | "en_GB" | "en_US" | "es" | "es_419" | "et" | "fa" | "fi" | "fil" | "fr"
  | "gu" | "he" | "hi" | "hr" | "hu" | "id" | "it" | "ja" | "kn" | "ko"
  | "lt" | "lv" | "ml" | "mr" | "ms" | "nl" | "no" | "pl" | "pt_BR" | "pt_PT"
  | "ro" | "ru" | "sk" | "sl" | "sr" | "sv" | "sw" | "ta" | "te" | "th"
  | "tr" | "uk" | "vi" | "zh_CN" | "zh_TW";
export type LangPref = Lang | "auto";
export type ThemePref = "light" | "dark" | "auto";

// Single source of truth for which locale codes exist — used by the
// matching logic below, and by anything else that wants to enumerate every
// shipped language (e.g. a settings page building its own <option> list
// instead of the static one in popup.html/sidepanel.html).
export const SUPPORTED_LANGS: readonly Lang[] = [
  "ar", "am", "bg", "bn", "ca", "cs", "da", "de", "el", "en", "en_GB", "en_US",
  "es", "es_419", "et", "fa", "fi", "fil", "fr", "gu", "he", "hi", "hr", "hu",
  "id", "it", "ja", "kn", "ko", "lt", "lv", "ml", "mr", "ms", "nl", "no", "pl",
  "pt_BR", "pt_PT", "ro", "ru", "sk", "sl", "sr", "sv", "sw", "ta", "te", "th",
  "tr", "uk", "vi", "zh_CN", "zh_TW",
];

// Of the 54 shipped locales, only these three are right-to-left scripts
// (Amharic, Hindi, Gujarati etc. all read left-to-right despite sometimes
// getting grouped colloquially with other Asian/Middle Eastern languages —
// RTL is a script property, not a region one). Used by
// isRtlLang()/applyDirection() below.
const RTL_LANGS: readonly Lang[] = ["ar", "fa", "he"];

/** True for a locale written right-to-left (Arabic, Persian, Hebrew). */
export function isRtlLang(lang: Lang): boolean {
  return (RTL_LANGS as readonly string[]).includes(lang);
}

// A couple of locale codes some browsers/OSes still hand back even though
// the language itself changed its ISO 639-1 code decades ago.
const LEGACY_LANG_ALIASES: Record<string, string> = { iw: "he", in: "id", tl: "fil" };

/**
 * Matches a raw BCP-47 browser/OS locale string (e.g. "en-US", "pt-BR",
 * "zh-Hant-TW", "nb", "es-419") to one of SUPPORTED_LANGS, or "en" if
 * nothing reasonable matches. Kept as a separate pure function (no chrome.*
 * calls) from resolveLang() below purely so it's directly unit-testable
 * without mocking the extension APIs — see tests/i18n.test.mjs.
 */
export function matchBrowserLang(rawLang: string | undefined | null): Lang {
  const norm = (rawLang || "").trim().toLowerCase().replace(/_/g, "-");
  if (!norm) return "en";
  const parts = norm.split("-");
  let base = LEGACY_LANG_ALIASES[parts[0]] || parts[0];
  // Norwegian Bokmål ("nb") / Nynorsk ("nn") both fold into the single "no"
  // this extension ships, matching what most single-Norwegian-locale
  // extensions do.
  if (base === "nb" || base === "nn") base = "no";
  const region = parts.slice(1).find((p) => p.length === 2 && /^[a-z]+$/.test(p)) || "";
  // UN M49 numeric region code — BCP-47 uses one of these instead of a
  // 2-letter country code for a handful of macro-regions, most relevantly
  // "419" (Latin America) in "es-419", which is exactly the locale this
  // extension ships as "es_419".
  const numericRegion = parts.slice(1).find((p) => /^\d{3}$/.test(p)) || "";
  const script = parts.slice(1).find((p) => p.length === 4) || ""; // e.g. "hant"/"hans"

  // Exact "base_REGION" match against a locale actually shipped as its own
  // distinct region variant (en_GB/en_US, es_419, pt_BR/pt_PT, zh_CN/zh_TW),
  // tried before any of the family-specific heuristics below.
  const exact = `${base}_${(region || numericRegion).toUpperCase()}`;
  if ((SUPPORTED_LANGS as readonly string[]).includes(exact)) return exact as Lang;

  // Family-specific region/script heuristics, for a region this extension
  // doesn't ship as its own exact variant (e.g. "en-AU", "es-MX", "pt-AO",
  // "zh-HK") — routes to the closest shipped variant instead of falling
  // through to a possibly-wrong default.
  if (base === "zh") {
    const traditional = script === "hant" || region === "tw" || region === "hk" || region === "mo";
    return traditional ? "zh_TW" : "zh_CN";
  }
  if (base === "pt") {
    return region === "br" ? "pt_BR" : "pt_PT";
  }
  if (base === "es") {
    // Spain (region "es" or no region at all) uses the generic "es"; every
    // other Spanish-speaking region (Latin America) maps to "es_419" — the
    // same "Latin American Spanish" convention Chrome/Android use.
    return region === "es" || !region ? "es" : "es_419";
  }
  if (base === "en") {
    if (region === "gb") return "en_GB";
    if (region === "us" || !region) return "en_US";
    return "en"; // every other English-speaking region (au/ca/nz/ie/za/in/...) — the neutral variant, rather than guessing which spelling convention it follows
  }

  // Plain base-language match — covers the overwhelming majority of
  // SUPPORTED_LANGS, which are single, region-less codes (e.g. "fr-CA" ->
  // "fr", "de-AT" -> "de", "ar-EG" -> "ar").
  if ((SUPPORTED_LANGS as readonly string[]).includes(base)) return base as Lang;

  return "en";
}

