export type StringKey = keyof typeof STRINGS.en;

/** Resolves an "auto"/concrete-language preference to a concrete Lang. */
export function resolveLang(pref: LangPref): Lang {
  if (pref !== "auto" && (SUPPORTED_LANGS as readonly string[]).includes(pref)) return pref as Lang;
  // auto (or an unrecognized/stale stored value): follow browser UI language
  const uiLang = chrome.i18n && chrome.i18n.getUILanguage ? chrome.i18n.getUILanguage() : navigator.language;
  return matchBrowserLang(uiLang);
}

export function t(key: StringKey, lang: Lang): string {
  const dict = STRINGS[lang] || STRINGS.en;
  // Cast to Record<string, string> rather than indexing the exact
  // per-locale literal type directly: with 54 locales in STRINGS, TS would
  // otherwise require every single locale dict to contain every StringKey
  // (including the invariant langXX keys, which by design live only in
  // `en` — see the langAr..langZhTW block above and its comment). The
  // runtime fallback below does the real work: a key missing from `dict`
  // (e.g. a locale's own langXX entry) falls through to STRINGS.en[key].
  return (dict as Record<string, string>)[key] || STRINGS.en[key] || key;
}

/** Applies translations to any element with data-i18n / data-i18n-title attributes. */
export function applyI18n(root: ParentNode | null, lang: Lang): void {
  const scope = root || document;
  scope.querySelectorAll<HTMLElement>("[data-i18n]").forEach((el) => {
    const key = el.getAttribute("data-i18n") as StringKey | null;
    if (key) el.textContent = t(key, lang);
  });
  scope.querySelectorAll<HTMLElement>("[data-i18n-title]").forEach((el) => {
    const key = el.getAttribute("data-i18n-title") as StringKey | null;
    if (key) el.title = t(key, lang);
  });
}

export function resolveTheme(pref: ThemePref): "light" | "dark" {
  if (pref === "light" || pref === "dark") return pref;
  const prefersDark = window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches;
  return prefersDark ? "dark" : "light";
}

export function applyTheme(pref: ThemePref): void {
  document.documentElement.setAttribute("data-theme", resolveTheme(pref));
}

/**
 * Sets <html dir="rtl"|"ltr"> for the resolved UI language, plus the
 * matching `lang` attribute (not RTL-specific, but the natural place to set
 * it alongside `dir`). `dir`
 * drives the browser's own bidi algorithm for native controls (<select>,
 * <input>), and is what the couple of `[dir="rtl"]` CSS overrides in
 * app.css/log.html key off; everything else directional in the CSS uses
 * logical properties (`text-align: start`, `margin-inline-start`,
 * `inset-inline-start`) that flip automatically from `dir` alone, with no
 * override needed. Called alongside applyI18n()/applyTheme() at every
 * entry point (app.ts, recorder.ts, log.ts) — always after applyI18n(),
 * since translated text length/alignment is exactly what `dir` affects.
 */
export function applyDirection(lang: Lang): void {
  document.documentElement.dir = isRtlLang(lang) ? "rtl" : "ltr";
  document.documentElement.lang = lang.replace("_", "-");
}

export interface Settings {
  theme: ThemePref;
  lang: LangPref;
  lastMode: "full" | "tab" | "area" | "screen";
  lastAudio: boolean;
  autoClipboard: boolean;
  videoQuality: "auto" | "low" | "medium" | "high";
  lastUiTab: "screenshot" | "video" | "settings";
  videoFormat: "webm" | "mp4";
  screenshotFormat: "png" | "webp";
  // Separate on/off switches for the draw/GIF annotation tool, one for
  // screenshots and one for video, since the two contexts warrant
  // independent control rather than one shared toggle. Both default to
  // true (opt-out, not opt-in) — the tool already existed for area mode
  // and nobody complained about that; only the scope grew when it expanded
  // to other modes, not the default-on behavior.
  screenshotDrawToolEnabled: boolean;
  videoDrawToolEnabled: boolean;
}

/** Small settings store shared by all extension pages. */
export const SettingsStore = {
  async get(): Promise<Settings> {
    const {
      theme = "auto", lang = "auto", lastMode = "full", lastAudio = true,
      autoClipboard = true, videoQuality = "auto", lastUiTab = "video",
      videoFormat = "webm", screenshotFormat = "png",
      screenshotDrawToolEnabled = true, videoDrawToolEnabled = true,
    } = await chrome.storage.local.get<Partial<Settings>>([
      "theme", "lang", "lastMode", "lastAudio", "autoClipboard", "videoQuality",
      "lastUiTab", "videoFormat", "screenshotFormat",
      "screenshotDrawToolEnabled", "videoDrawToolEnabled",
    ]);
    return {
      theme, lang, lastMode, lastAudio, autoClipboard, videoQuality, lastUiTab, videoFormat, screenshotFormat,
      screenshotDrawToolEnabled, videoDrawToolEnabled,
    };
  },
  async set(partial: Partial<Settings>): Promise<void> {
    await chrome.storage.local.set(partial);
  },
};
